using System;

public abstract class Enemy
{
    public string Name { get; }
    public int Health { get; protected set; }
    protected Enemy(string name, int health) { Name = name; Health = health; }
    public virtual void TakeDamage(int amount) => Health = Math.Max(0, Health - amount);
    public abstract int AttackDamage();
    public virtual string Describe() => $"{Name} ({Health} HP)";
}

public class Goblin : Enemy
{
    public Goblin(string name) : base(name, 30) { }
    public override int AttackDamage() => 5;
}

public sealed class Golem : Enemy
{
    public Golem() : base("Golem", 120) { }
    public override int AttackDamage() => 15;
    public override void TakeDamage(int amount) => base.TakeDamage(Math.Max(0, amount - 10));   // stone skin
    public override string Describe() => base.Describe() + " [stone]";
}

class Program
{
    static void Main()
    {
        Enemy[] wave = { new Goblin("Snik"), new Golem() };
        foreach (Enemy e in wave)
        {
            e.TakeDamage(25);
            Console.WriteLine($"{e.Describe()} hits for {e.AttackDamage()}");
        }
    }
}

