using System;
using System.Collections.Generic;
using System.Linq;

public abstract class Enemy
{
    public string Name { get; }
    public int Health { get; protected set; }

    protected Enemy(string name, int health)
    {
        Name = name;
        Health = health;
    }

    public bool IsDead => Health <= 0;

    public virtual void TakeDamage(int amount)
    {
        Health = Math.Max(0, Health - amount);
    }

    public abstract int AttackDamage();

    public virtual string Describe() => $"{Name} ({Health} HP)";
}

public class Goblin : Enemy
{
    public Goblin(string name) : base(name, 30) { }

    public override int AttackDamage() => 5;
}

public class Troll : Enemy
{
    public Troll(string name) : base(name, 80) { }

    public override int AttackDamage() => 12;

    // Thick skin: half damage, but the "never below 0" rule still lives in the base class.
    public override void TakeDamage(int amount) => base.TakeDamage(amount / 2);
}

public sealed class DragonBoss : Enemy
{
    public DragonBoss() : base("Dragon", 200) { }

    public override int AttackDamage() => Health <= 100 ? 40 : 25;

    public override string Describe() => base.Describe() + " [BOSS]";
}

