using System;
using System.Collections.Generic;
using System.Linq;

public abstract class Turret
{
    public string Name { get; }
    public int Level { get; private set; } = 1;

    protected Turret(string name)
    {
        Name = name;
    }

    // Every turret must say how hard it hits.
    public abstract int Damage { get; }

    // Most turrets cost this much; a child may change it.
    public virtual int UpgradeCost => Level * 100;

    public void Upgrade()
    {
        if (Level >= 5) throw new InvalidOperationException("Already at the top level.");
        Level++;
    }

    public override string ToString() => $"{Name} L{Level}: {Damage} dmg";
}

public class ArrowTurret : Turret
{
    public ArrowTurret() : base("Arrow") { }

    public override int Damage => 5 * Level;
}

public class CannonTurret : Turret
{
    public CannonTurret() : base("Cannon") { }

    public override int Damage => 20 + 10 * (Level - 1);

    public override int UpgradeCost => Level * 150;
}

