using System;
using System.Collections.Generic;
using System.Linq;

// One small part that does one job well, reused by anything that needs it.
public class Health
{
    public int Max { get; }
    public int Current { get; private set; }

    public Health(int max)
    {
        if (max <= 0) throw new ArgumentOutOfRangeException(nameof(max));
        Max = max;
        Current = max;
    }

    public bool IsEmpty => Current == 0;

    public void Damage(int amount) => Current = Math.Max(0, Current - Math.Max(0, amount));

    public void Heal(int amount) => Current = Math.Min(Max, Current + Math.Max(0, amount));
}

public class Player
{
    public string Name { get; }
    public Health Health { get; }   // has-a, not is-a

    public Player(string name, int maxHealth)
    {
        Name = name;
        Health = new Health(maxHealth);
    }
}

public class Barrel
{
    public Health Health { get; } = new Health(20);

    public bool Explodes => Health.IsEmpty;
}
